///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name etnChangePage
 * @description etn Change Page 처리
 * @param {*} tab tab
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.etnChangePage = async function (tab) {
    form = (document.etnListForm || { elements: [] });
    const lastSaveStatCdInt = parseInt($c.util.getComponent('dma_readDataVO').get('lastSaveStatCd'));
    if (lastSaveStatCdInt === 0 && tab > 1) {
        await $c.win.alert('발행증권에 관한 사항을 먼저 저장해주세요.');
        return;
    } else {
        if (lastSaveStatCdInt === 1 && tab > 2) {
            await $c.win.alert('발행증권2(손실제한)에 관한 사항을 먼저 저장해주세요.');
            return;
        } else {
            if (lastSaveStatCdInt === 2 && tab > 3) {
                await $c.win.alert('발행회사에 관한 사항을 먼저 저장해주세요.');
                return;
            } else {
                if (lastSaveStatCdInt === 3 && tab > 4) {
                    await $c.win.alert('보증인/제3자LP에 관한 사항을 먼저 저장해주세요.');
                    return;
                }
            }
        }
    }
    if (tab === 1) {
        $c.util.getComponent('dma_EtnChangePageReq').set('method', 'lossLimitViewIsuTab');
    } else {
        if (tab === 2) {
            $c.util.getComponent('dma_EtnChangePageReq').set('method', 'lossLimitViewIsuTab2');
        } else {
            if (tab === 3) {
                return;
            } else {
                if (tab === 4) {
                    $c.util.getComponent('dma_EtnChangePageReq').set('method', 'lossLimitViewSrtyLpTab');
                } else {
                    $c.util.getComponent('dma_EtnChangePageReq').set('method', 'lossLimitViewAttachFileTab');
                }
            }
        }
    }
    form.action = 'LossLimitEtnList.do';
    await scwin.tx_fn_EtnChangePage();
};

/**
 * @method
 * @name register
 * @description register 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.register = async function () {

    if( !await scwin.confirmJob('I') )  return;

    if("" + dma_readDataVO.get("applStatusCd") + "" === '02') {
        await $c.win.alert('반송된 신청입니다. 발행증권에 관한 사항 탭부터 다시 저장해야 합니다.');
        return;
    }

    scwin.removeComma(3);

    if( !fn_validate(3) ) return;

    form = (document.etnListForm || { elements: [] });

    form.action = 'LossLimitEtnList.do';
    $c.util.getComponent('dma_RegisterReq').set('method', 'lossLimitSaveIsurTab');
    await scwin.tx_fn_Register();

};

/**
 * @method
 * @name etnSub
 * @description etn Sub 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.etnSub = async function () {
    if (!await scwin.confirmJob('S')) {
        return;
    }
    form = (document.etnListForm || { elements: [] });
    form.action = "LossLimitEtnList.do";
    $c.util.getComponent('dma_EtnSubReq').set('method', 'lossLimitSubmitList');
    await scwin.tx_fn_EtnSub();
};

/**
 * @method
 * @name search
 * @description search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function () {
    form = (document.etnListForm || { elements: [] });
    form.action = "LossLimitEtnList.do";
    $c.util.getComponent('dma_SearchReq').set('method', 'lossLimitSearchList');
    await scwin.tx_fn_Search();
};

/**
 * @method
 * @name calIsuLimit
 * @description cal Isu Limit 처리
 * @returns {void}
 * @hidden N
 */
scwin.calIsuLimit = function () {
    form = (document.etnListForm || { elements: [] });
    if ($c.util.getComponent('ipt_eqtycap').getValue()=== 0 || ($c.util.getComponent('ipt_eqtycap').getValue() == null ? '' : String($c.util.getComponent('ipt_eqtycap').getValue())) === '') {
        $c.util.getComponent("ipt_isuLimit").setValue('');
    } else {
        $c.util.getComponent("ipt_isuLimit").setValue(Math.floor(($c.util.getComponent('ipt_isuTotamt').getValue()* 100 / $c.util.getComponent('ipt_eqtycap').getValue()) * 100) / 100);
    }
};

/**
 * @method
 * @name removeComma
 * @description remove Comma 처리
 * @param {*} tab tab
 * @returns {void}
 * @hidden N
 */
scwin.removeComma = function (tab) {

    form = (document.etnListForm || { elements: [] });
    const elem = $c.util.getComponent('etnListForm').elements;

    if(tab === 1) {
        for(let i=0; i<elem.length; i++)
        {
            if(elem[i].name.indexOf('etnIsuQty') >= 0 ||
                elem[i].name.indexOf('isuOrgnVal') >= 0 ||
                // elem[i].name.indexOf('traceYdMult') >= 0 ||
                elem[i].name.indexOf('lpHdQty') >= 0 ||
                elem[i].name.indexOf('declSpd') >= 0 ||
                elem[i].name.indexOf('halfwyRedmptUnit') >= 0 ||
                elem[i].name.indexOf('etnIsuPrc') >= 0
            ) fn_ObjValueResetRmComma2(elem[i]);
        }
    } else if(tab === 2) {
        for(let i=0; i<elem.length; i++)
        {
            if(elem[i].name.indexOf('expMaxYd') >= 0 ||
                elem[i].name.indexOf('expMaxRedmptPrc') >= 0 ||
                elem[i].name.indexOf('expMaxLossRt') >= 0 ||
                elem[i].name.indexOf('expMinRedmptPrc') >= 0 ||
                elem[i].name.indexOf('basIdx') >= 0 ||
                elem[i].name.indexOf('isuTheoPrc') >= 0 ||
                elem[i].name.indexOf('earyRedmptBas1Idx0') >= 0 ||
                elem[i].name.indexOf('earyRedmptPrc0') >= 0 ||
                elem[i].name.indexOf('earyRedmptBas1Idx') >= 0 ||
                elem[i].name.indexOf('earyRedmptBas2Idx') >= 0 ||
                elem[i].name.indexOf('earyRedmptPrc') >= 0 ||
                elem[i].name.indexOf('rngacrlEarngLwlmtBasIdx') >= 0 ||
                elem[i].name.indexOf('rngacrlEarngUplmtBasIdx') >= 0 ||
                elem[i].name.indexOf('rngacrlTotBzDys') >= 0 ||
                elem[i].name.indexOf('partcRt1RngLwlmtBasIdx') >= 0 ||
                elem[i].name.indexOf('partcRt1RngUplmtBasIdx') >= 0 ||
                elem[i].name.indexOf('partcRt2RngLwlmtBasIdx') >= 0 ||
                elem[i].name.indexOf('partcRt2RngUplmtBasIdx') >= 0 ||
                elem[i].name.indexOf('valuPrc1HistVoltPd') >= 0 ||
                elem[i].name.indexOf('valuPrc2HistVoltPd') >= 0
            ) fn_ObjValueResetRmComma2(elem[i]);
        }
    } else if(tab === 3) {
        for(let i=0; i<elem.length; i++)
        {
            if(elem[i].name.indexOf('totAsstAmt') >= 0 ||
                elem[i].name.indexOf('totDebtAmt') >= 0 ||
                elem[i].name.indexOf('totCap') >= 0 ||
                elem[i].name.indexOf('cap') >= 0 ||
                elem[i].name.indexOf('bzProftAmt') >= 0 ||
                elem[i].name.indexOf('ordnincmAmt') >= 0 ||
                elem[i].name.indexOf('netincmAmt') >= 0 ||
                elem[i].name.indexOf('bzActivCashFlowAmt') >= 0 ||
                elem[i].name.indexOf('fbzNetcap') >= 0 ||
                elem[i].name.indexOf('totRiskAmt') >= 0 ||
                elem[i].name.indexOf('reqPersisPrincCapVal') >= 0 ||
                (elem[i].name.indexOf('ncr') >= 0 && elem[i].name.indexOf('ncrAcntclsYymm') < 0) ||
                elem[i].name.indexOf('eqtycap') >= 0 ||
                elem[i].name.indexOf('isuTotamt') >= 0 ||
                elem[i].name.indexOf('isuLimit') >= 0
            ) fn_ObjValueResetRmComma2(elem[i]);
        }
    } else if(tab === 4) {
        for(let i=0; i<elem.length; i++)
        {
            if(elem[i].name.indexOf('totAsstAmt') >= 0 ||
                elem[i].name.indexOf('totDebtAmt') >= 0 ||
                elem[i].name.indexOf('totCap') >= 0 ||
                elem[i].name.indexOf('cap') >= 0 ||
                elem[i].name.indexOf('bzProftAmt') >= 0 ||
                elem[i].name.indexOf('ordnincmAmt') >= 0 ||
                elem[i].name.indexOf('netincmAmt') >= 0 ||
                elem[i].name.indexOf('bzActivCashFlowAmt') >= 0 ||
                elem[i].name.indexOf('basEqtycap') >= 0 ||
                elem[i].name.indexOf('riskAsstVal') >= 0 ||
                elem[i].name.indexOf('etnSrtyPrincCapRto') >= 0 ||
                elem[i].name.indexOf('srtyEqtycap') >= 0 ||
                elem[i].name.indexOf('srtyIsuTotamt') >= 0 ||
                elem[i].name.indexOf('srtyMiscIsuAmt') >= 0 ||
                elem[i].name.indexOf('srtyIsuLimit') >= 0 ||
                elem[i].name.indexOf('lpFbzNetcap') >= 0 ||
                elem[i].name.indexOf('lpTotRiskAmt') >= 0 ||
                elem[i].name.indexOf('lpReqPersisPrincCapVal') >= 0 ||
                elem[i].name.indexOf('lpNcr') >= 0
            ) fn_ObjValueResetRmComma2(elem[i]);
        }
    }
};

/**
 * @method
 * @name insertComma
 * @description insert Comma 처리
 * @param {*} tab tab
 * @returns {void}
 * @hidden N
 */
scwin.insertComma = function (tab) {

    // form = document.etnListForm;
    const elem = $c.util.getComponent('etnListForm').elements;

    if(tab === 1) {
        for(let i=0; i<elem.length; i++)
        {
            if(elem[i].name.indexOf('etnIsuQty') >= 0 ||
                elem[i].name.indexOf('isuOrgnVal') >= 0 ||
                // elem[i].name.indexOf('traceYdMult') >= 0 ||
                elem[i].name.indexOf('lpHdQty') >= 0 ||
                elem[i].name.indexOf('declSpd') >= 0 ||
                elem[i].name.indexOf('halfwyRedmptUnit') >= 0 ||
                elem[i].name.indexOf('etnIsuPrc') >= 0
            )
            fn_ObjValueSetComma(elem[i]);
        }
    } else if(tab === 2) {
        for(let i=0; i<elem.length; i++)
        {
            if(elem[i].name.indexOf('expMaxYd') >= 0 ||
                elem[i].name.indexOf('expMaxRedmptPrc') >= 0 ||
                elem[i].name.indexOf('expMaxLossRt') >= 0 ||
                elem[i].name.indexOf('expMinRedmptPrc') >= 0 ||
                elem[i].name.indexOf('basIdx') >= 0 ||
                elem[i].name.indexOf('isuTheoPrc') >= 0 ||
                elem[i].name.indexOf('earyRedmptBas1Idx0') >= 0 ||
                elem[i].name.indexOf('earyRedmptPrc0') >= 0 ||
                elem[i].name.indexOf('earyRedmptBas1Idx') >= 0 ||
                elem[i].name.indexOf('earyRedmptBas2Idx') >= 0 ||
                elem[i].name.indexOf('earyRedmptPrc') >= 0 ||
                elem[i].name.indexOf('rngacrlEarngLwlmtBasIdx') >= 0 ||
                elem[i].name.indexOf('rngacrlEarngUplmtBasIdx') >= 0 ||
                elem[i].name.indexOf('rngacrlTotBzDys') >= 0 ||
                elem[i].name.indexOf('partcRt1RngLwlmtBasIdx') >= 0 ||
                elem[i].name.indexOf('partcRt1RngUplmtBasIdx') >= 0 ||
                elem[i].name.indexOf('partcRt2RngLwlmtBasIdx') >= 0 ||
                elem[i].name.indexOf('partcRt2RngUplmtBasIdx') >= 0 ||
                elem[i].name.indexOf('valuPrc1HistVoltPd') >= 0 ||
                elem[i].name.indexOf('valuPrc2HistVoltPd') >= 0
            ) fn_ObjValueSetComma(elem[i]);
        }
    } else if(tab === 3) {
        for(let i=0; i<elem.length; i++)
        {
            if(elem[i].name.indexOf('totAsstAmt') >= 0 ||
                elem[i].name.indexOf('totDebtAmt') >= 0 ||
                elem[i].name.indexOf('totCap') >= 0 ||
                elem[i].name.indexOf('cap') >= 0 ||
                elem[i].name.indexOf('bzProftAmt') >= 0 ||
                elem[i].name.indexOf('ordnincmAmt') >= 0 ||
                elem[i].name.indexOf('netincmAmt') >= 0 ||
                elem[i].name.indexOf('bzActivCashFlowAmt') >= 0 ||
                elem[i].name.indexOf('fbzNetcap') >= 0 ||
                elem[i].name.indexOf('totRiskAmt') >= 0 ||
                elem[i].name.indexOf('reqPersisPrincCapVal') >= 0 ||
                (elem[i].name.indexOf('ncr') >= 0 && elem[i].name.indexOf('ncrAcntclsYymm') < 0) ||
                elem[i].name.indexOf('eqtycap') >= 0 ||
                elem[i].name.indexOf('isuTotamt') >= 0 ||
                elem[i].name.indexOf('isuLimit') >= 0
            ) fn_ObjValueSetComma(elem[i]);
        }
    } else if(tab === 4) {
        for(let i=0; i<elem.length; i++)
        {
            if(elem[i].name.indexOf('totAsstAmt') >= 0 ||
                elem[i].name.indexOf('totDebtAmt') >= 0 ||
                elem[i].name.indexOf('totCap') >= 0 ||
                elem[i].name.indexOf('cap') >= 0 ||
                elem[i].name.indexOf('bzProftAmt') >= 0 ||
                elem[i].name.indexOf('ordnincmAmt') >= 0 ||
                elem[i].name.indexOf('netincmAmt') >= 0 ||
                elem[i].name.indexOf('bzActivCashFlowAmt') >= 0 ||
                elem[i].name.indexOf('basEqtycap') >= 0 ||
                elem[i].name.indexOf('riskAsstVal') >= 0 ||
                elem[i].name.indexOf('etnSrtyPrincCapRto') >= 0 ||
                elem[i].name.indexOf('srtyEqtycap') >= 0 ||
                elem[i].name.indexOf('srtyIsuTotamt') >= 0 ||
                elem[i].name.indexOf('srtyMiscIsuAmt') >= 0 ||
                elem[i].name.indexOf('srtyIsuLimit') >= 0 ||
                elem[i].name.indexOf('lpFbzNetcap') >= 0 ||
                elem[i].name.indexOf('lpTotRiskAmt') >= 0 ||
                elem[i].name.indexOf('lpReqPersisPrincCapVal') >= 0 ||
                elem[i].name.indexOf('lpNcr') >= 0
            ) fn_ObjValueSetComma(elem[i]);
        }
    } else if(tab === 5) {

    }
};

/**
 * @method
 * @name confirmJob
 * @description 업무 처리 확인 — "[저장] 하시겠습니까?" 확인창(as-is 공통 fn_isProcess 의 의미 보존 · pcc/fil 반입 후보)
 * @param {*} gubun 처리 구분(I 저장 · U 수정 · D 삭제 · S 제출 · R 해제 · DSCL 안내문작성)
 * @returns {Promise<Boolean>} 확인이면 true
 * @hidden N
 */
scwin.confirmJob = async function (gubun) {
    const job = { I: "저장", U: "수정", D: "삭제", S: "제출", R: "해제", DSCL: "안내문작성" }[gubun] || gubun;
    scwin.lastJob = job;  // 결과 알림(alertJobResult)이 같은 처리명을 쓴다 — as-is 전역 LastJob
    return $c.win.confirm("[" + job + "] 하시겠습니까?");
};
